def total_for(values):
    total = 0
    for value in values:
        total += value
    return total

def total_while(values):
    total = 0
    i = 0
    while i < len(values):
        total += values[i]
        i += 1
    return total

print(total_for([3, 6]), total_while([3, 6]))
